type UpdateTransactionFromImportParams struct {
	Type          string
	Time          time.Time
	PortfolioID   sql.NullString
	SecurityID    sql.NullString
	CashAccountID sql.NullString
	Units         float64
	Price         Decimal
	Fees          int64
	Taxes         int64
	CashDelta     int64
	Currency      string
	PriceCurrency sql.NullString
	FxRate        Decimal
	ID            string
}

// ConfirmImport's reconciliation update; also refreshes FX fields, unlike UpdateTransaction.
func (q *Queries) UpdateTransactionFromImport(ctx context.Context, arg UpdateTransactionFromImportParams) (*Transaction, error) {
	row := q.db.QueryRowContext(ctx, updateTransactionFromImport,
		arg.Type,
		arg.Time,
		arg.PortfolioID,
		arg.SecurityID,
		arg.CashAccountID,
		arg.Units,
		arg.Price,
		arg.Fees,
		arg.Taxes,
		arg.CashDelta,
		arg.Currency,
		arg.PriceCurrency,
		arg.FxRate,
		arg.ID,
	)
	var i Transaction
	err := row.Scan(
		&i.ID,
		&i.Type,
		&i.Time,
		&i.PortfolioID,
		&i.SecurityID,
		&i.CashAccountID,
		&i.Units,
		&i.Price,
		&i.Fees,
		&i.Taxes,
		&i.CashDelta,
		&i.Currency,
		&i.Source,
		&i.CreatedAt,
		&i.DocumentID,
		&i.PriceCurrency,
		&i.FxRate,
		&i.TransferID,
		&i.ScheduleID,
		&i.ScheduledFor,
		&i.Note,
	)
	return &i, err
}
